import { useLocale, useTranslations } from 'next-intl'
import { cn } from '@/lib/cn'
import { formatCorpusDate } from '@/i18n/format'

/** The line every answer ends with: it was generated by an AI system, and the corpus date when known. */
export function AiNotice({ corpusAsOf, demo, className }: { corpusAsOf?: string; demo?: boolean; className?: string }) {
  const t = useTranslations('chiedi.aiNotice')
  const locale = useLocale()
  const date = formatCorpusDate(corpusAsOf, locale)
  return (
    <p className={cn('text-caption text-ink-3', className)}>
      {t('base')}
      {date && <> {t(demo ? 'corpusDemo' : 'corpus', { date })}</>}
    </p>
  )
}
